'use strict';
const G=Golf,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',flag:'M5 21V3m0 0 13 4-13 5',golf:'M8 19V3l11 4-11 5M6 17c-3 0-4 1-4 2s3 2 7 2 7-1 7-2-2-2-4-2',chart:'M4 20V11m5 9V4m6 16v-7m5 7V7',history:'M3 11a9 9 0 1 1 2.6 7M3 4v7h7m2-4v6l4 2',friends:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-3.9M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm8 0a4 4 0 0 1 0 8',user:'M20 21a8 8 0 0 0-16 0M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',plus:'M12 5v14M5 12h14',minus:'M5 12h14',check:'m5 12 4 4L19 6',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15Zm5.5 13 5 5',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-8-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',leaf:'M20 3C7 2 2 7 5 15c4 7 15 4 15-12ZM5 20 16 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3l-1 3-3 1-2 3 2 3-1 3 3 2 1 3h6l1-3 3-1 2-3-2-3 1-3-3-2-1-3Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',share:'M12 16V3m-4 4 4-4 4 4M8 10H4v11h16V10h-4',edit:'m15 3 6 6-11 11-7 1 1-7Zm-11 11 6 6M13 5l6 6',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v6l4 2',target:'M12 2v3m0 14v3M2 12h3m14 0h3M12 5a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm0 4a3 3 0 1 0 0 6 3 3 0 0 0 0-6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 8v6m0-10v.1',trophy:'M8 3h8v7a4 4 0 0 1-8 0Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 2v6m-4 0h8',calendar:'M8 2v4m8-4v4M4 4h16v17H4ZM4 10h16',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',pause:'M8 5v14m8-14v14',close:'m6 6 12 12M6 18 18 6',undo:'M3 10h10a7 7 0 0 1 7 7M3 10l5-5m-5 5 5 5',cloud:'M7 18a5 5 0 1 1 .5-10A6 6 0 0 1 19 9a4.5 4.5 0 1 1-1 9Z',copy:'M9 9h12v12H9ZM6 15H3V3h12v3',book:'M4 3h13a3 3 0 0 1 3 3v15H6a2 2 0 0 1-2-2Zm0 14h16'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.flag}"/></svg>`;
const img=(cls='',alt='青野球场时光 · AI意境配图')=>`<img class="${cls}" src="assets/glass/retreat.jpg" alt="${alt}">`;
const action=(a,label,cls='',attrs='')=>`<button class="${cls}" data-action="${a}" ${attrs}>${label}</button>`;
const go=(path,label,cls='',attrs='')=>action('go',label,cls,`data-path="${esc(path)}" ${attrs}`);
const av=(p,i=0)=>`<span class="avatar a${i%4}">${esc(p.name?.slice(0,1)||'球')}</span>`;
const pill=(t,c='green')=>`<span class="tag ${c}">${esc(t)}</span>`;
const rate=(n,d)=>d?Math.round(n/d*100)+'%':'—';
const storagePrefix=new URLSearchParams(location.search).has('qa')?'qingye.h5.qa':'qingye.h5';
let mode;try{mode=localStorage.getItem(storagePrefix+'.mode')||'demo';}catch{mode='demo';}
let db,loadError='',saveError='',undo=null,edit=null,technical=false,statsSize=18,statsDays=0,courseFilter='all',courseQuery='',histFilter='all',histQuery='',scoreHalf=null,modalCallback=null,lastFocus=null,demoDistance=158,locationMessage='',route={name:'home',id:null,q:new URLSearchParams()};
const key=()=>`${storagePrefix}.${mode}.v3`;
function load(){try{let raw=localStorage.getItem(key());if(!raw){const old=localStorage.getItem(`${storagePrefix}.${mode}.v2`);if(old){const upgraded=G.validateBackup(JSON.parse(old));localStorage.setItem(`${storagePrefix}.${mode}.pre-v3`,old);localStorage.setItem(key(),JSON.stringify({...upgraded,courses:upgraded.courses.filter(c=>!c.publicData)}));G.validateBackup(JSON.parse(localStorage.getItem(key())));raw=localStorage.getItem(key());}}db=raw?G.validateBackup(JSON.parse(raw)):mode==='demo'?G.seeded():G.initial();db.dbRevision=db.dbRevision||0;loadError='';}catch(e){db=mode==='demo'?G.seeded():G.initial();try{const old=localStorage.getItem(`${storagePrefix}.${mode}.v2`);if(old)db=G.validateBackup(JSON.parse(old));}catch(ignore){}loadError='数据升级未完成：'+e.message+'。原始记录已保留，保存已暂停。';}technical=db.settings.technical;}

load();
function persist(next){if(loadError){toast('请先导出原始数据，当前保存已暂停');return false;}try{const raw=localStorage.getItem(key()),stored=raw?JSON.parse(raw):null;if(stored&&(stored.dbRevision||0)!==(db.dbRevision||0)){toast('另一页面已更新记录，请刷新后重试');return false;}next.dbRevision=(db.dbRevision||0)+1;localStorage.setItem(key(),JSON.stringify({...next,courses:next.courses.filter(c=>!c.publicData)}));db=next;saveError='';return true;}catch(e){saveError='保存失败：'+e.message;toast(saveError);return false;}}

function update(fn){const next=G.clone(db);try{fn(next);return persist(next);}catch(e){toast(e.message);return false;}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function nav(path){if(edit&&!path.startsWith('score/'+edit.id)&&!path.startsWith('card/'+edit.id)){confirmBox('更正还没有提交','离开后将放弃这次更正，原来的成绩不受影响。',()=>{edit=null;nav(path);},'放弃更正');return;}if(location.hash==='#/'+path){render();window.scrollTo(0,0);}else location.hash='/'+path;}
function readRoute(){const [p,q='']=(location.hash.slice(2)||'home').split('?');const parts=p.split('/');route={name:parts[0],id:parts[1]||null,q:new URLSearchParams(q)};}
function round(id=route.id){return edit?.id===id?edit.copy:db.rounds.find(r=>r.id===id);}
const active=()=>db.rounds.find(r=>r.status==='active');
const allSorted=()=>[...db.rounds].sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt-a.updatedAt);
function modal(title,body,footer=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-handle"></div><div class="row"><h2>${esc(title)}</h2>${action('close',icon('close'),'icon-btn','aria-label="关闭弹窗"')}</div>${body}${footer}</section></div>`;$('#modal-root button')?.focus({preventScroll:true});}
function closeModal(){$('#modal-root').innerHTML='';modalCallback=null;lastFocus?.focus?.();}
function confirmBox(title,body,cb,label='确认'){modalCallback=cb;modal(title,`<p>${esc(body)}</p>`,`<div class="modal-actions">${action('close','取消','btn outline')}${action('confirm',esc(label),'btn primary')}</div>`);modalCallback=cb;}
function empty(title,sub,path,label='开始记分'){return `<div class="empty"><div class="empty-icon">${icon('flag')}</div><h3>${esc(title)}</h3><p>${esc(sub)}</p>${path?go(path,esc(label),'btn secondary small'):''}</div>`;}
function section(title,path,label='查看全部'){return `<div class="section-head"><h2>${esc(title)}</h2>${path?go(path,esc(label)+icon('chevron'),'text-link'):''}</div>`;}
function title(t,s){return `<div class="title-block"><div class="eyebrow">QINGYE GOLF JOURNAL</div><h1>${esc(t)}</h1>${s?`<p>${esc(s)}</p>`:''}</div>`;}
function metrics(s){return `<div class="metrics"><div class="metric"><b>${s.rounds}</b><span>已结束球局</span></div><div class="metric"><b>${s.best??'—'}</b><span>18 洞最佳</span></div><div class="metric"><b>${s.holes}</b><span>累计记录球洞</span></div></div>`;}
function roundCard(r){const s=G.summary(r,'me');return go((r.status==='active'?'score/':'result/')+r.id,`${img('round-thumb')}<div class="round-copy"><h3>${esc(r.courseName)}</h3><p>${esc(r.date.replaceAll('-','.'))} · ${r.holes.length} 洞 · ${r.players.length} 人</p><div style="margin-top:5px">${pill(R.isFinished(r)?(s.complete?'已结束':'部分完成'):r.status==='active'?'进行中':'已暂停',r.status==='active'?'green':'gray')}</div></div><div class="round-number"><strong>${s.totalText}</strong><small>${s.played}/${r.holes.length} 洞 · ${s.diffText}</small></div>`,'card round-card');}
function topbar(){const primary=['home','play','courses','profile'].includes(route.name)&&!route.q.has('select');if(primary)return `<header class="topbar"><a class="brand" href="#/home"><img src="assets/glass/wordmark.webp" alt="青野"><div><b>青野</b><small>QINGYE GOLF</small></div></a><div class="top-meta">${route.name==='home'?pill('自在挥杆','gray'):''}${go('settings',icon('settings'),'icon-btn','aria-label="设置"')}</div></header>`;const names={courses:'选择球场',course:'球场详情',create:'创建对局',manual:'添加我的球场',score:edit?'更正成绩':'本轮记分',card:'完整记分卡',result:'本轮成绩',history:'历史记录',stats:'数据统计',friends:'我的球友',settings:'设置与数据',distance:'球道测距',guide:'球场小册',feedback:'信息与问题反馈',about:'关于青野高尔夫'};return `<header class="topbar secondary">${action('back',icon('back'),'icon-btn back','aria-label="返回"')}<div class="topbar-title">${names[route.name]||'青野高尔夫'}</div>${route.name==='score'?action('pause',icon('pause'),'icon-btn','aria-label="暂停球局"'):go('home',icon('home'),'icon-btn','aria-label="回首页"')}</header>`;}
function bottomNav(){const n=route.name;return `<nav class="bottom-nav" aria-label="主导航">${[['home','home','首页'],['play','flag','记分'],['courses','pin','球场'],['profile','user','我的']].map(([p,i,t])=>go(p,icon(i)+t,`nav-item ${n===p?'active':''}`,n===p?'aria-current="page"':'')).join('')}</nav>`;}
function home(){const s=G.stats(db),a=active(),recent=allSorted().filter(r=>R.isFinished(r)).slice(0,2);return `<div class="greeting"><div><h1>去球场，找回好状态</h1><p>你好，${esc(db.profile.name)}。今天也为热爱挥杆。</p></div><div class="leaf">${icon('leaf')}</div></div><div class="hero">${img()}<span class="hero-corner">A GOOD DAY FOR GOLF</span><div class="hero-text"><div class="eyebrow">LESS DISTRACTION. MORE GOLF.</div><h2>下一杆，值得期待。</h2><p>让每一次挥杆，都有迹可循。</p></div></div>${action(a?'resume':'start',`<span class="cta-left">${icon('flag')}<span>${a?'继续本轮记分':'开始一场好球'}${a?`<small style="display:block;margin-top:3px">${esc(a.courseName)} · 第 ${a.currentHole} 洞</small>`:''}</span></span>${icon('arrow')}`,'btn primary full hero-cta',a?`data-id="${a.id}"`:'')}${metrics(s)}<div class="shortcuts">${[['courses','pin','选择球场'],['stats','chart','数据统计'],['history','history','历史记录'],['friends','friends','我的球友']].map(([p,i,t])=>go(p,`<span class="box">${icon(i)}</span>${t}`,'shortcut')).join('')}</div>${section('最近的球场时光','history','全部记录')}${recent.length?recent.map(roundCard).join(''):empty('第一场好球，从这里开始','记录成绩，也记录每一次进步。','courses?select=1')}<div class="footer-note">ENJOY THE GAME, ENJOY THE MOMENT.</div>`;}
function play(){const a=active(),paused=db.rounds.filter(r=>r.status==='paused');return `${title('专注当下的每一杆','轻松开局，把时间留给球场。')}${a?`<div class="hero" style="height:175px">${img()}<div class="hero-text"><div class="eyebrow">YOUR ONGOING ROUND</div><h2 style="font-size:21px">${esc(a.courseName)}</h2><p>第 ${a.currentHole} 洞 · ${a.holes.length} 洞 · ${a.players.length} 位球友</p></div></div>${action('resume','继续本轮 '+icon('arrow'),'btn primary full',`data-id="${a.id}" style="margin:14px 0"`)}`:empty('今天，想去哪里挥杆？','选择球场，邀请你的同组球友。','courses?select=1')}${action('start',icon('plus')+' 新建一场球局',a?'btn outline full':'btn secondary full')}${section('暂存的球局')}${paused.length?paused.map(r=>`<div class="card"><div class="row"><div><h3>${esc(r.courseName)}</h3><p class="tiny">${r.date} · ${r.players.length} 人 · 已记录 ${G.summary(r,'me').played}/${r.holes.length} 洞</p></div>${pill('已暂停','gold')}</div><div class="round-actions">${go('result/'+r.id,'查看成绩','btn outline small')}${action('resume','继续记分','btn secondary small',`data-id="${r.id}"`)}</div></div>`).join(''):`<p class="muted" style="text-align:center;padding:20px">暂无暂停的球局</p>`}<div class="notice">${icon('info')}<span>每次有效记分都会自动保存到当前浏览器。可以随时离开，下次接着记。</span></div>`;}
function courseCards(){let cs=db.courses.filter(c=>(!courseQuery||`${c.name}${c.city}`.includes(courseQuery))&&(courseFilter==='favorites'?db.favorites.includes(c.id):courseFilter==='recent'?db.rounds.some(r=>r.courseId===c.id):true));return cs.length?cs.map(c=>`<article class="card course-card"><div class="course-cover photo-${c.photo||0}">${img()}<span class="badge">${esc(c.tag||'我的球场')}</span>${action('favorite',icon('star'),`star ${db.favorites.includes(c.id)?'selected':''}`,`data-id="${c.id}" aria-label="${db.favorites.includes(c.id)?'取消收藏':'收藏'}${esc(c.name)}"`)}</div><div class="course-info"><div class="row"><h3>${esc(c.name)}</h3></div><div class="row"><span class="mini-info">${icon('pin')}${esc(c.city||'自定义')} · ${c.holes} 洞 · Par ${c.pars.reduce((a,b)=>a+b,0)}</span>${pill(c.demo?'示例球场':'我的球场','gray')}</div><div class="divider"></div><div class="row"><span class="tiny">${esc(c.subtitle||'每一场，都值得认真记录')}</span>${go((route.q.has('select')?'create/':'course/')+c.id,(route.q.has('select')?'选用球场':'查看详情')+icon('chevron'),'btn secondary small')}</div></div></article>`).join(''):empty('没有找到合适的球场','试试其他关键词，或添加你的球场。','manual','手动添加球场');}
function coursesPage(){return `${title('下一场，去哪里？','在熟悉的球道，发现新的可能。')}<div class="search">${icon('search')}<input id="course-search" value="${esc(courseQuery)}" placeholder="搜索球场名称、城市" aria-label="搜索球场"></div><div class="chips">${[['all','全部球场'],['recent','最近打过'],['favorites','我的收藏']].map(([v,t])=>action('course-filter',t,`chip ${courseFilter===v?'active':''}`,`data-value="${v}"`)).join('')}</div><div id="course-list">${courseCards()}</div>${go('manual',icon('plus')+' 没找到球场？手动添加','btn outline full')}<p class="tiny" style="text-align:center;margin-top:13px">内置球场资料为演示样例，照片为风格配图。</p>`;}
function courseDetail(){const c=db.courses.find(c=>c.id===route.id);if(!c)return empty('球场不存在','请返回选择其他球场。','courses','选择球场');return `<div class="hero" style="height:210px">${img()}<div class="hero-text"><div class="eyebrow">${esc(c.tag||'MY GOLF COURSE')}</div><h2 style="font-size:22px">${esc(c.name)}</h2><p>${esc(c.city||'我的球场')} · ${c.holes} 洞</p></div></div><div class="metrics"><div class="metric"><b>${c.holes}</b><span>球洞数量</span></div><div class="metric"><b>${c.pars.reduce((a,b)=>a+b,0)}</b><span>标准杆</span></div><div class="metric"><b>${c.tees.length}</b><span>发球台</span></div></div>${section('球场资料')}<div class="card"><p class="muted">${esc(c.subtitle||'属于你的球场，属于你的记录。')}</p><div class="divider"></div><div class="row"><span class="muted">可选发球台</span><span class="tiny">${esc(c.tees.join(' / '))}</span></div><div class="status-line">${icon('info')}${c.demo?'示例资料 · 请在实际下场前核对标准杆':'用户创建 · 标准杆以你维护的资料为准'}</div></div>${section('逐洞标准杆')}<div class="card">${[0,9].filter(n=>c.pars.length>n).map(n=>`<p class="tiny" style="margin-bottom:10px">${n?'后九洞 · IN':'前九洞 · OUT'}</p><div class="course-pars" style="margin-bottom:16px">${c.pars.slice(n,n+9).map((p,i)=>`<div><small>${n+i+1}</small>${p}</div>`).join('')}</div>`).join('')}</div><div class="notice">${icon('target')}<span>此球场尚未提供经过核验的果岭坐标。可正常记分，测距仅支持示意体验。</span></div><div class="round-actions">${action('favorite',icon('star')+(db.favorites.includes(c.id)?'已收藏':'收藏球场'),'btn outline',`data-id="${c.id}"`)}${go('create/'+c.id,'在这里开始 '+icon('arrow'),'btn primary')}</div>`;}
function ensureDraft(){const cid=route.id||db.draft?.courseId||db.courses[0].id;if(!db.draft||db.draft.courseId!==cid){const c=db.courses.find(c=>c.id===cid);if(!c)return null;db.draft={courseId:cid,date:G.date(),time:new Date().toTimeString().slice(0,5),holes:c.holes===9?'front':'all',start:1,players:[{id:'me',name:db.profile.name,tee:c.tees[0]}]};}return db.draft;}
function createPage(){const d=ensureDraft();if(!d)return empty('请先选择球场','','courses?select=1','选择球场');const c=db.courses.find(c=>c.id===d.courseId);return `<div class="steps"><span class="active"></span><span class="active"></span><span></span></div><div class="card row" style="padding:11px">${img('round-thumb')}<div class="grow"><h3>${esc(c.name)}</h3><p class="tiny" style="margin-top:5px">${esc(c.city||'我的球场')} · ${c.holes} 洞 · ${c.demo?'示例资料':'手动资料'}</p></div>${go('courses?select=1','更换','text-link')}</div><div class="form-label">开球时间 <span>留住今天的好时光</span></div><div class="grid2"><input type="date" id="draft-date" aria-label="打球日期" value="${d.date}"><input type="time" id="draft-time" aria-label="开球时间" value="${d.time}"></div><div class="form-label">本轮球洞</div><div class="grid3">${[['front','前 9 洞'],['back','后 9 洞'],['all','完整 18 洞']].filter(([v])=>c.holes===18||v==='front').map(([v,t])=>action('draft-holes',t,`choice ${d.holes===v?'active':''}`,`data-value="${v}"`)).join('')}</div>${d.holes==='all'?`<div class="form-label">从哪里出发</div><div class="grid2">${[1,10].map(n=>action('draft-start','第 '+n+' 洞',`choice ${d.start===n?'active':''}`,`data-value="${n}"`)).join('')}</div>`:''}<div class="row"><div class="form-label">同组球友 <span>${d.players.length}/4 人</span></div>${d.players.length<4?action('add-player',icon('plus')+' 添加','text-link'):''}</div><div class="card">${d.players.map((p,i)=>`<div class="player-row">${av(p,i)}<div class="grow"><b>${esc(p.name)}</b><small>${p.id==='me'?'我 · 记分员':'同组球友'}</small></div><select data-tee="${p.id}" aria-label="${esc(p.name)}的发球台">${c.tees.map(t=>`<option ${p.tee===t?'selected':''}>${esc(t)}</option>`).join('')}</select>${p.id==='me'?'':action('remove-player',icon('close'),'icon-btn',`data-id="${p.id}" aria-label="移除${esc(p.name)}"`)}</div>`).join('')}<div class="tiny">一个人就能为全组代记，球友无需注册。</div></div><div class="form-label">记分方式</div><div class="card row"><div class="row start">${icon('flag')}<div><h3>标准比杆赛</h3><p class="tiny" style="margin-top:4px">记录实际总杆，自动计算成绩</p></div></div>${pill('已选择')}</div><div class="notice">${icon('info')}<span>总杆已包含罚杆。推杆、罚杆等技术数据可在记分时选填。</span></div><div class="dock">${action('create-round','开始本轮记分 '+icon('arrow'),'btn primary')}</div>`;}
function table(r,full=false){const half=scoreHalf??(r.currentHole>9?'back':'front');let holes=full?r.holes:r.holes.filter(h=>half==='front'?h.number<=9:h.number>9);if(!holes.length)holes=r.holes;return `${!full&&r.holes.length===18?`<div class="segment">${[['front','前九洞 · OUT'],['back','后九洞 · IN']].map(([v,t])=>action('half',t,half===v?'active':'',`data-value="${v}"`)).join('')}</div>`:''}<div class="table-scroll"><table class="${full?'full-table':''}"><thead><tr><th>球洞</th>${holes.map(h=>`<th class="${h.number===r.currentHole?'current':''}">${h.number}</th>`).join('')}<th>总杆</th></tr></thead><tbody><tr class="par-row"><td>Par</td>${holes.map(h=>`<td>${h.par}</td>`).join('')}<td>—</td></tr>${r.players.map(p=>`<tr><td>${esc(p.id==='me'?'我':p.name)}</td>${holes.map(h=>{const s=r.scores[p.id][h.number],diff=s?s.strokes-h.par:0;return `<td>${action('cell',s?s.strokes:'—',`cell-btn ${s?(diff<0?'under':diff>0?'over':''):'blank'} ${r.currentHole===h.number&&r.currentPlayer===p.id?'selected':''}`,`data-rid="${r.id}" data-id="${p.id}" data-hole="${h.number}" aria-label="${esc(p.name)}第${h.number}洞${s?s.strokes+'杆':'未记分'}"`)}</td>`;}).join('')}<td>${G.summary(r,p.id).totalText}</td></tr>`).join('')}</tbody></table></div>`;}
function scorePage(){const r=round();if(!r)return empty('没有找到这场球局','','play','返回记分');if(R.isFinished(r)&&!edit){nav('result/'+r.id);return '';}const h=r.holes.find(h=>h.number===r.currentHole)||r.holes[0],p=r.players.find(p=>p.id===r.currentPlayer)||r.players[0],s=r.scores[p.id][h.number],sum=G.summary(r,p.id);return `${edit?'<div class="readonly">更正模式 · 修改完成后点击底部“提交更正”</div>':''}<div class="score-top"><div><h2>${esc(r.courseName)}</h2><p class="tiny">${r.date} · ${r.players.length} 位球友</p></div><span class="save-state ${saveError?'error':''}">${icon(saveError?'info':'check')}${saveError?'保存失败':edit?'尚未提交':'已保存到本机'}</span></div><div class="hole-heading"><h1>第 ${h.number} 洞<span>Par ${h.par}</span></h1><div class="progress"><b>${sum.played}</b> / ${r.holes.length} 洞<br>已记录进度</div></div>${table(r)}<div class="player-tabs">${r.players.map((p,i)=>action('select-player',av(p,i)+`<span>${esc(p.id==='me'?'我':p.name)}</span>${r.scores[p.id][h.number]?'<span class="check">✓</span>':''}`,`player-tab ${p.id===r.currentPlayer?'active':''}`,`data-id="${p.id}" aria-label="切换到${esc(p.name)}"`)).join('')}</div><div class="card score-panel"><div class="row"><div class="eyebrow">${esc(p.id==='me'?'我的':p.name+'的')}本洞总杆</div>${p.withdrawn?pill('已退出','gold'):pill(s?'已记分':'待记分',s?'green':'gray')}</div><div class="stepper">${action('score-step',icon('minus'),'step-btn',`data-delta="-1" aria-label="减少总杆" ${p.withdrawn?'disabled':''}`)}${action('score-input',s?s.strokes:h.par,`score-value ${s?'':'pending'}`,`aria-label="输入总杆" ${p.withdrawn?'disabled':''}`)}${action('score-step',icon('plus'),'step-btn plus',`data-delta="1" aria-label="增加总杆" ${p.withdrawn?'disabled':''}`)}</div><p class="score-detail">${s?`${s.strokes-h.par===0?'平标准杆 · Par':s.strokes-h.par<0?'低于标准杆 '+(h.par-s.strokes)+' 杆':'高于标准杆 '+(s.strokes-h.par)+' 杆'}`:'建议值 · 点击下方按钮才会记录'}</p>${!s?action('record-par',`按 Par ${h.par} 记录 ${icon('check')}`,'quick-par',p.withdrawn?'disabled':''):pill('总杆已包含罚杆','gray')}<div class="score-bottom"><span>当前累计 <b>${sum.totalText}</b> 杆 · ${sum.diffText}</span><div>${undo?.rid===r.id?action('undo','撤销',''):''}${s?action('clear-score','清空本洞',''):''}</div></div></div>${action('toggle-tech',`<span>${icon('grid')}详细记录 <small style="color:#9baa90">选填</small></span><span>${technical?'收起 −':'展开 +'}</span>`,'technical-toggle')}${technical?`<div class="card technical">${!s?'<p class="tiny">先记录总杆，即可填写推杆和命中数据。</p>':''}<div class="tech-row"><span>推杆数</span><input type="number" min="0" max="30" inputmode="numeric" data-tech="putts" aria-label="推杆数" placeholder="未记录" value="${s?.putts??''}" ${!s?'disabled':''}></div><div class="tech-row"><span>罚杆 <small class="tiny">已含于总杆</small></span><input type="number" min="0" max="30" inputmode="numeric" data-tech="penalties" aria-label="罚杆数" placeholder="未记录" value="${s?.penalties??''}" ${!s?'disabled':''}></div>${[['fairway','球道命中'],['gir','标准杆上果岭']].map(([k,t])=>`<div class="tech-row"><span>${t}</span>${k==='fairway'&&h.par===3?'<span class="tiny">Par 3 不适用</span>':`<div class="mini-chips">${[['null','未记'],['true','命中'],['false','未中']].map(([v,txt])=>action('tech-hit',txt,`mini-chip ${String(s?.[k]??null)===v?'active':''}`,`data-key="${k}" data-value="${v}" ${!s?'disabled':''}`)).join('')}</div>`}</div>`).join('')}</div>`:''}<div class="score-tools">${go('card/'+r.id,icon('grid')+'完整记分卡')}${go('distance/'+r.id,icon('target')+'查看距离')}${edit?action('cancel-edit',icon('close')+'取消更正'):go('result/'+r.id,icon('chart')+'本轮成绩')}</div>${p.withdrawn?action('withdraw','恢复这位球友参与','btn secondary full',`data-id="${p.id}" style="margin-top:12px"`):action('withdraw','球友中途退出','text-link',`data-id="${p.id}"`)}<div class="dock">${action('previous','上一洞','btn outline',r.playOrder.indexOf(h.number)===0?'disabled':'')}${edit?action('save-edit','提交更正 '+icon('check'),'btn primary'):action('next',(r.playOrder.indexOf(h.number)===r.playOrder.length-1?'检查并结束本轮':'保存并进入下一洞')+icon('arrow'),'btn primary')}</div>`;}
function cardPage(){const r=round();if(!r)return empty('球局不存在','','history','历史记录');return `${title('每一杆，都有记录',r.courseName)}<div class="notice">${icon('info')}<span>左右滑动查看所有球洞，点击格子可查看或修改。未记录的球洞保持空白。</span></div>${table(r,true)}${section('已记录实际杆数')}<div class="card">${r.players.map(p=>{const s=G.summary(r,p.id);return `<div class="rank-row">${av(p)}<div class="grow"><b>${esc(p.name)}</b><small>已记 ${s.played}/${r.holes.length} 洞 · 前九 ${s.frontN?s.front:'—'} / 后九 ${s.backN?s.back:'—'}</small></div><span class="total">${s.totalText}</span><span class="diff">${s.diffText}</span></div>`;}).join('')}</div>${go((R.isFinished(r)&&!edit?'result/':'score/')+r.id,'返回本轮 '+icon('arrow'),'btn primary full')}`;}
function resultPage(){const r=round();if(!r)return empty('球局不存在','','history','历史记录');const s=G.summary(r,'me'),rank=G.ranking(r);return `<div class="result-hero"><div class="eyebrow">${R.isFinished(r)?'A ROUND TO REMEMBER':'YOUR ROUND SO FAR'}</div><h2>${esc(r.courseName)}</h2><p class="tiny" style="color:#b8cdb0;margin-top:7px">${r.date.replaceAll('-','.')} · ${r.holes.length} 洞 · ${r.players.length} 人</p><div class="result-score">${s.totalText}<small>杆</small></div><div class="result-meta">${s.diffText} · 已记录 ${s.played}/${r.holes.length} 洞</div>${pill(R.isFinished(r)?(s.complete?'本轮已结束':'本轮部分完成'):'当前成绩 · 球局未结束')}<div class="result-substats"><div><b>${s.frontN?s.front:'—'}</b><small>前九 · ${s.frontN} 洞</small></div><div><b>${s.backN?s.back:'—'}</b><small>后九 · ${s.backN} 洞</small></div><div><b>${s.puttN?s.putts:'—'}</b><small>推杆 · 已记 ${s.puttN} 洞</small></div></div></div>${section(rank.final?'同组总杆排名':'同组成绩')}<div class="card">${rank.rows.map((p,i)=>`<div class="rank-row"><span class="rank-number ${p.rank===1?'winner':''}">${p.rank===1?icon('trophy'):p.rank||'—'}</span>${av(p,i)}<div class="grow"><b>${esc(p.name)} ${p.id==='me'?pill('我'):''}</b><small>${p.withdrawn?'中途退出 · ':''}${p.played}/${r.holes.length} 洞 · ${esc(p.tee)}</small></div><span class="total">${p.totalText}</span><span class="diff">${p.diffText}</span></div>`).join('')}</div><p class="tiny">${rank.final?'按实际总杆排名，未按发球台难度校正。':rank.comparable?'目前各人已记球洞相同，显示当前排序。':'已记录球洞或完成状态不同，暂不显示最终名次。'}</p>${section('这一轮的小小收获')}<div class="grid3">${[['Birdie',s.types.birdie],['Par',s.types.par],['Bogey',s.types.bogey]].map(([t,n])=>`<div class="card" style="text-align:center;padding:17px 4px"><b style="font-size:24px;font-weight:450">${n}</b><p class="tiny" style="margin-top:5px">${t}</p></div>`).join('')}</div>${go('card/'+r.id,icon('grid')+' 查看完整记分卡','btn outline full')}${!R.isFinished(r)?`<div class="round-actions">${action('resume','继续记分','btn secondary',`data-id="${r.id}"`)}${action('finish','结束本轮','btn primary',`data-id="${r.id}"`)}</div>`:`<div class="round-actions">${action('begin-edit',icon('edit')+' 更正成绩','btn outline',`data-id="${r.id}"`)}${action('share',icon('share')+' 分享成绩','btn primary',`data-id="${r.id}"`)}</div>`}<div class="row" style="margin-top:18px">${go('stats','查看个人统计 '+icon('chevron'),'text-link')}${action('delete-round',icon('trash')+' 删除球局','text-link text-danger',`data-id="${r.id}"`)}</div>`;}
function historyList(){const rs=allSorted().filter(r=>(histFilter==='all'||(histFilter==='completed'?R.isFinished(r):!R.isFinished(r)))&&(!histQuery||r.courseName.includes(histQuery)||r.date.includes(histQuery)));return rs.length?rs.map(roundCard).join(''):empty('这里还没有球局','试试其他筛选，或开始新一轮记录。','courses?select=1');}
function historyPage(){const s=G.stats(db);return `${title('那些挥杆的好日子','每一场球，都是你的高尔夫故事。')}<div class="history-banner"><div><small>累计已结束球局</small><b>${s.rounds}<small> 场</small></b></div><div><small>完整 18 洞最佳</small><b>${s.best??'—'}<small> 杆</small></b></div></div><div class="search">${icon('search')}<input id="history-search" value="${esc(histQuery)}" placeholder="搜索球场或日期" aria-label="搜索历史记录"></div><div class="chips">${[['all','全部记录'],['active','未结束'],['completed','已结束']].map(([v,t])=>action('hist-filter',t,`chip ${histFilter===v?'active':''}`,`data-value="${v}"`)).join('')}</div><div id="history-list">${historyList()}</div>`;}
function trend(s){if(!s.trend.length)return empty('还没有完整球局','完成一轮后，在这里看见自己的进步。');const vals=s.trend.map(t=>t.total),low=Math.min(...vals)-3,high=Math.max(...vals)+3;const points=vals.map((v,i)=>[20+i*280/Math.max(1,vals.length-1),100-(v-low)/(high-low)*75]);return `<div class="chart"><svg viewBox="0 0 320 120" role="img" aria-label="最近${vals.length}轮总杆趋势"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c8ddba" stop-opacity=".5"/><stop offset="1" stop-color="#eef5e8" stop-opacity="0"/></linearGradient></defs>${[25,60,100].map(y=>`<path d="M10 ${y}H310" stroke="#edf1e7" stroke-dasharray="3 4"/>`).join('')}<path d="M${points.map(p=>p.join(',')).join(' L')} L${points.at(-1)[0]},112 L${points[0][0]},112Z" fill="url(#chartfill)"/><path d="M${points.map(p=>p.join(',')).join(' L')}" fill="none" stroke="#799f67" stroke-width="2.2"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#799f67" stroke-width="2"/><text x="${x}" y="${y-12}" text-anchor="middle" font-size="11" fill="#6d8a5f">${vals[i]}</text>`).join('')}</svg><div class="chart-labels">${s.trend.map(t=>`<span>${t.date.slice(5).replace('-','/')}</span>`).join('')}</div></div>`;}
function statsPage(){const s=G.stats(db,statsSize,statsDays);return `${title('每一点进步，都算数','数据来自你的记录，成长由你自己定义。')}<div class="row"><div class="segment" style="flex:1">${[18,9].map(n=>action('stats-size',n+' 洞',n===statsSize?'active':'',`data-value="${n}"`)).join('')}</div><select id="stats-days" aria-label="统计时间范围" style="width:107px;padding:9px 8px;font-size:11px">${[[0,'全部时间'],[30,'最近 30 天'],[90,'最近 90 天']].map(([v,t])=>`<option value="${v}" ${statsDays===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="stat-cards"><div class="card stat-card feature"><div class="stat-icon">${icon('flag')}</div><b>${s.average===null?'—':s.average.toFixed(1)}</b><p>平均总杆 · 完整 ${statsSize} 洞</p></div><div class="card stat-card"><div class="stat-icon">${icon('trophy')}</div><b>${s.best??'—'}</b><p>最佳成绩 · ${s.complete} 轮有效样本</p></div><div class="card stat-card"><div class="stat-icon">${icon('calendar')}</div><b>${s.complete}</b><p>完整 ${statsSize} 洞球局</p></div><div class="card stat-card"><div class="stat-icon">${icon('target')}</div><b>${s.puttN?(s.putts/s.puttN).toFixed(1):'—'}</b><p>每洞推杆 · 已记录 ${s.puttN} 洞</p></div></div>${section('最近的成绩趋势')}<div class="card"><div class="row"><span class="tiny">完整 ${statsSize} 洞 · 总杆数</span><span class="tiny">越低越好</span></div>${trend(s)}</div>${section('技术数据')}<div class="card">${[['球道命中率',s.fw,s.fwN],['标准杆上果岭',s.gir,s.girN]].map(([t,n,d])=>`<div class="stat-bar"><div class="row"><span>${t}</span><b>${rate(n,d)}</b></div><div class="track"><div class="fill" style="width:${d?n/d*100:0}%"></div></div><small>命中 ${n} / 有效记录 ${d} 洞</small></div>`).join('')}<p class="tiny">仅统计明确填写的记录。Par 3 不计入球道命中率。</p></div>${section('逐洞成绩分布')}<div class="card">${[['eagle','Eagle'],['birdie','Birdie'],['par','Par'],['bogey','Bogey'],['double','Double Bogey'],['other','其他成绩']].map(([k,t])=>`<div class="row" style="padding:8px 0"><span class="muted">${t}</span><b style="font-size:13px">${s.types[k]}</b></div>`).join('')}</div><p class="tiny">完整 9 洞与 18 洞分别统计；未完成球局不进入平均总杆与最佳成绩。</p>`;}
function friendsPage(){return `${title('好球，和好友一起','常一起打球的人，下次一键加入。')}${action('new-friend',icon('plus')+' 添加球友','btn primary full','style="margin-bottom:20px"')}${db.friends.length?db.friends.map((p,i)=>{const rs=allSorted().filter(r=>r.players.some(x=>x.id===p.id));const last=rs.find(r=>G.summary(r,p.id).played);return `<div class="card friend-card"><div class="player-row">${av(p,i+1)}<div class="grow"><b>${esc(p.name)}</b><small>${esc(p.remark||'常用球友')}</small></div>${action('edit-friend',icon('edit'),'icon-btn',`data-id="${p.id}" aria-label="编辑${esc(p.name)}"`)}${action('remove-friend',icon('trash'),'icon-btn',`data-id="${p.id}" aria-label="移除${esc(p.name)}"`)}</div><div class="friend-stats"><span><b>${rs.length}</b>场共同球局</span><span>最近成绩 <b>${last?G.summary(last,p.id).totalText:'—'}</b>杆</span></div>${rs.length?action('friend-detail','查看共同球局 '+icon('chevron'),'text-link',`data-id="${p.id}" style="margin-top:7px"`):''}</div>`;}).join(''):empty('把常打球的朋友加进来','只需一个昵称，球友无需注册。')}`;}
function menuRow(i,label,path,end=''){return go(path,icon(i)+`<span class="grow">${label}</span>${end?`<span class="end-text">${end}</span>`:''}`+icon('chevron'),'menu-row');}
function profilePage(){const s=G.stats(db);return `<div class="profile-head"><div class="eyebrow">MY GOLF JOURNAL</div><div class="profile-person"><div class="profile-avatar">${esc(db.profile.name[0])}</div><div class="grow"><h1>${esc(db.profile.name)}</h1><p>${esc(db.profile.bio)}</p>${db.profile.handicap!==null?pill('自填差点 '+db.profile.handicap):pill('每一杆，都是新的开始')}</div>${action('edit-profile',icon('edit'),'icon-btn','aria-label="编辑个人资料"')}</div><div class="metrics"><div class="metric"><b>${s.rounds}</b><span>已结束球局</span></div><div class="metric"><b>${s.best??'—'}</b><span>18 洞最佳</span></div><div class="metric"><b>${s.courseCount}</b><span>打过的球场</span></div></div></div>${section('我的高尔夫')}<div class="card list-menu">${menuRow('friends','我的球友','friends',db.friends.length+' 位')}${menuRow('history','历史记录','history')}${menuRow('chart','数据统计','stats')}${action('show-favorites',icon('star')+'<span class="grow">球场收藏</span><span class="end-text">'+db.favorites.length+' 个</span>'+icon('chevron'),'menu-row')}</div><div class="card list-menu">${menuRow('settings','设置与数据管理','settings')}${action('about',icon('info')+'<span class="grow">关于青野</span><span class="end-text">轻盈而专注</span>'+icon('chevron'),'menu-row')}</div><div class="notice">${icon('cloud')}<span>当前为 H5 本地版，记录保存在此浏览器。建议定期备份，换设备时可以导入恢复。</span></div><div class="footer-note">让热爱，有迹可循。</div>`;}
function settingsPage(){return `${title('让记分，更顺手','按你的习惯，照顾好每一份记录。')}<div class="card"><div class="row"><div><h3>距离单位</h3><p class="tiny" style="margin-top:4px">球场长度和测距统一使用</p></div><div class="mini-chips">${[['yd','码'],['m','米']].map(([v,t])=>action('unit',t,`mini-chip ${db.settings.unit===v?'active':''}`,`data-value="${v}"`)).join('')}</div></div><div class="divider"></div><div class="row"><div><h3>默认展开详细记录</h3><p class="tiny" style="margin-top:4px">推杆、罚杆与命中数据</p></div>${action('pref-tech',db.settings.technical?'已开启':'已关闭',`chip ${db.settings.technical?'active':''}`)}</div></div>${section('数据管理')}<div class="card list-menu">${action('export',icon('download')+'<span class="grow">导出数据备份</span>'+icon('chevron'),'menu-row')}${action('import',icon('upload')+'<span class="grow">从备份恢复</span>'+icon('chevron'),'menu-row')}${action('cloud-info',icon('cloud')+'<span class="grow">数据保存方式</span><span class="end-text">当前浏览器</span>'+icon('chevron'),'menu-row')}${loadError?action('retry-upgrade','重新尝试升级','btn outline full')+action('raw-export',icon('download')+'<span class="grow">导出无法读取的原始数据</span>'+icon('chevron'),'menu-row'):''}</div><div class="notice">${icon('info')}<span>清理浏览器数据、使用无痕模式或更换设备都可能导致记录不可用。备份会包含球友昵称与成绩。</span></div>${section('体验模式')}<div class="card"><div class="row"><div><h3>${mode==='demo'?'正在体验示例数据':'正在使用我的记录'}</h3><p class="tiny" style="margin-top:6px">两种模式的数据独立保存，互不影响。</p></div>${pill(mode==='demo'?'示例':'个人')}</div>${action('switch-mode',mode==='demo'?'切换到我的记录':'体验示例数据','btn secondary full','style="margin-top:16px"')}${mode==='demo'?action('reset-demo','恢复初始示例','text-link','style="margin:10px auto 0"'):''}</div>${section('关于与隐私')}<div class="card"><p class="muted">无需登录即可记录。H5 版不会上传你的球局或定位轨迹；头像、昵称由你自行填写。测距示意不代表真实球场，不能用于实际击球判断。</p></div>`;}
function distancePage(){const r=round();if(!r)return empty('先开启一场球局','测距与当前球洞同步。','play','开始记分');const unit=db.settings.unit==='yd'?'码':'米',v=db.settings.unit==='yd'?demoDistance:Math.round(demoDistance*.9144);return `<div class="row"><div><h3>${esc(r.courseName)}</h3><p class="tiny">第 ${r.currentHole} 洞 · Par ${r.holes.find(h=>h.number===r.currentHole)?.par}</p></div>${pill('测距示意','gold')}</div><div class="notice warning">${icon('info')}<span>这是交互演示，球道与距离均为示例，不代表真实位置，不用于实际下场。</span></div><div class="card distance-card"><div class="eyebrow">果岭中心 · 示例距离</div><div class="distance-value">${v}<span style="font-size:13px;letter-spacing:0;margin-left:8px">${unit}</span></div><div class="row"><div class="distance-side"><b>${v-12}</b><small>前参考点</small></div><div class="distance-side"><b>${v+14}</b><small>后参考点</small></div></div></div><div class="map-panel"><svg viewBox="0 0 360 300" role="img" aria-label="演示球道示意图"><rect width="360" height="300" fill="#e7eddf"/><path d="M20 30Q80 0 100 65T50 170T75 300M300 0Q240 50 295 110T310 300" fill="none" stroke="#d9e4ce" stroke-width="30"/><path d="M170 290C110 220 120 180 160 150S220 110 205 55" stroke="#b4c79c" stroke-width="93" fill="none" stroke-linecap="round"/><path d="M170 290C140 220 150 185 175 157S213 100 205 55" stroke="#c1d3ac" stroke-width="65" fill="none" stroke-linecap="round"/><ellipse cx="205" cy="51" rx="41" ry="27" fill="#9ab984"/><path d="M256 50q18 22-3 36t-19-15Z" fill="#ece3c7"/><path d="M115 180q-25 10-12 32t26-5Z" fill="#ece3c7"/><path d="M67 50q-20 20-25 65t40 15-15-80" fill="#b8d2d0"/><path d="M175 254 205 51" stroke="white" stroke-width="2" stroke-dasharray="5 6"/><circle cx="175" cy="254" r="13" fill="#fff" opacity=".6"/><circle cx="175" cy="254" r="7" fill="#236346" stroke="#fff" stroke-width="3"/><path d="M205 55V25l20 7-20 8" stroke="#375f33" fill="#375f33" stroke-width="2"/><rect x="185" y="135" width="52" height="24" rx="12" fill="white"/><text x="211" y="151" text-anchor="middle" fill="#4f7041" font-size="10">${v} ${unit}</text><text x="12" y="24" font-size="9" fill="#99aa8a">N ↑</text></svg><span class="map-tag">球道示意 · 非真实地理地图</span>${action('demo-distance',icon('target'),'map-button','aria-label="移动示例位置"')}</div><p class="tiny" style="margin-top:10px">点击定位图标，体验移动后距离变化。</p><div class="round-actions">${action('toggle-unit','切换为'+(db.settings.unit==='yd'?'米':'码'),'btn outline')}${go('score/'+r.id,'记本洞成绩 '+icon('arrow'),'btn primary')}</div><div class="card" style="margin-top:20px"><h3>真实测距需要什么？</h3><p class="muted" style="margin-top:8px">需要球场核验过的果岭坐标与手机位置。当前未接入真实点位，所以不会把演示读数当成 GPS 测距。</p>${action('locate',icon('target')+' 检查手机定位','btn secondary small','style="margin-top:14px"')}<p class="tiny" id="location-message" style="margin-top:9px">${esc(locationMessage||'仅在你点击后请求定位，位置不会保存或上传。')}</p></div>`;}
function manualPage(){return `${title('添加你的球场','没有收录，也能好好记分。')}<form data-form="manual"><div class="card"><div class="field"><label>球场名称</label><input name="name" required maxlength="45" placeholder="输入球场名称"></div><div class="field"><label>所在城市（选填）</label><input name="city" maxlength="20" placeholder="例如：杭州"></div><div class="field"><label>球洞数量</label><select name="count" id="manual-count"><option value="18">18 洞</option><option value="9">9 洞</option></select></div></div><div class="form-label">逐洞标准杆 <span>请按球场记分卡核对</span></div><div class="card holes-grid" id="manual-holes">${manualHoles(18)}</div><label class="check-row"><input type="checkbox" required><span>我已核对每洞标准杆，默认 Par 4 仅为编辑初值。</span></label><button type="submit" class="btn primary full">保存球场并开始 ${icon('arrow')}</button></form>`;}
function manualHoles(n){return Array.from({length:n},(_,i)=>`<div class="hole-edit"><label>第 ${i+1} 洞</label><select name="par-${i+1}" aria-label="第${i+1}洞标准杆">${[3,4,5].map(p=>`<option value="${p}" ${p===4?'selected':''}>Par ${p}</option>`).join('')}</select></div>`).join('');}
function render(){readRoute();const routes={home,play,courses:coursesPage,course:courseDetail,create:createPage,score:scorePage,card:cardPage,result:resultPage,history:historyPage,stats:statsPage,friends:friendsPage,profile:profilePage,settings:settingsPage,distance:distancePage,manual:manualPage,guide:typeof golfGuidePage==='function'?golfGuidePage:home,feedback:typeof feedbackPage==='function'?feedbackPage:home,about:typeof aboutPage==='function'?aboutPage:home};const primary=['home','play','courses','profile'].includes(route.name)&&!route.q.has('select'),dock=['score','create'].includes(route.name);const html=(routes[route.name]||home)();$('#app').innerHTML=topbar()+`${mode==='demo'?`<div class="demo-strip"><span><i class="dot"></i>示例体验 · 不影响你的真实记录</span>${action('switch-mode','使用我的记录 →')}</div>`:''}${loadError?`<div class="notice warning" style="margin:12px">${esc(loadError)}</div>`:''}<main class="page ${primary?'':'no-tabs'} ${dock?'with-dock':''}">${html}</main>${primary?bottomNav():''}`;document.title=(route.name==='home'?'青野高尔夫':'青野 · '+({score:'本轮记分',result:'本轮成绩',stats:'数据统计',courses:'球场',history:'历史记录',profile:'我的'}[route.name]||'高尔夫记分'));}

function saveRound(next,original=round(),remember=false){
 const previous=()=>({rid:next.id,pid:next.currentPlayer,hole:next.currentHole,previous:G.clone(original.scores[next.currentPlayer]?.[next.currentHole]??null)});
 if(edit?.id===next.id){edit.copy=next;saveError='';if(remember)undo=previous();return true;}
 const ok=update(d=>{const n=d.rounds.findIndex(r=>r.id===next.id);if(n<0)throw Error('球局不存在');d.rounds[n]=next;});if(ok&&remember)undo=previous();return ok;
}
function moveTo(hole,pid){const r=round();if(!r)return;const n=G.clone(r);n.currentHole=Number(hole);if(pid)n.currentPlayer=pid;if(saveRound(n)){scoreHalf=hole>9?'back':'front';render();}}
function writeScore(score){const r=round(),old=G.clone(r);try{const n=G.setScore(r,r.currentPlayer,r.currentHole,score);if(saveRound(n,old,true))render();}catch(e){toast(e.message);}}
function current(){const r=round();const h=r?.holes.find(h=>h.number===r.currentHole);return {r,h,p:r?.players.find(p=>p.id===r.currentPlayer),s:r?.scores[r.currentPlayer]?.[r.currentHole]};}
function changeDraft(fn){if(update(d=>{if(!d.draft)throw Error('请重新选择球场');fn(d.draft);})){render();}}
function resume(id){const r=db.rounds.find(r=>r.id===id);if(!r)return toast('球局不存在');if(R.isFinished(r))return nav('result/'+id);if(update(d=>{d.rounds.forEach(x=>{if(x.status==='active')x.status='paused';});d.rounds.find(x=>x.id===id).status='active';})){scoreHalf=null;nav('score/'+id);}}
function start(){const a=active();if(a)confirmBox('先暂停当前球局？','当前成绩会保留在“记分”中，可以随时回来继续。',()=>{if(update(d=>d.rounds.find(r=>r.id===a.id).status='paused'))nav('courses?select=1');},'暂停并新建');else nav('courses?select=1');}
function createRound(){const draft=G.clone(db.draft),c=db.courses.find(c=>c.id===draft?.courseId);if(!draft||!c)return toast('请先选择球场');const build=()=>{let r;try{if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.date))throw Error('请选择打球日期');r=G.makeRound(c,draft.players,draft);}catch(e){return toast(e.message);}if(update(d=>{d.rounds.forEach(x=>{if(x.status==='active')x.status='paused';});d.rounds.unshift(r);d.draft=null;})){undo=null;scoreHalf=null;nav('score/'+r.id);toast('球局已创建，开始享受今天');}};if(active())confirmBox('开始新球局','正在进行的球局会暂停并保留。',build,'开始新球局');else build();}
function addPlayerModal(){const draft=db.draft;if(!draft||draft.players.length>=4)return toast('同组最多 4 人');const fs=db.friends.filter(f=>!draft.players.some(p=>p.id===f.id));modal('添加同组球友',`<p>可以选择常用球友，也可以只填一个昵称。</p>${fs.length?`<div class="card list-menu">${fs.map((f,i)=>action('choose-friend',av(f,i+1)+`<span class="grow">${esc(f.name)}</span>${icon('plus')}`,'menu-row',`data-id="${f.id}"`)).join('')}</div>`:''}<form data-form="temp-player"><div class="field"><label>临时球友昵称</label><input name="name" placeholder="输入球友昵称" required maxlength="20"></div><label class="check-row"><input type="checkbox" name="save"><span>同时添加到常用球友</span></label><button class="btn primary full" type="submit">加入本轮</button></form>`);}
function finish(id){const r=db.rounds.find(r=>r.id===id);if(!r||R.isFinished(r))return;const count=r.players.reduce((n,p)=>n+G.summary(r,p.id).played,0);if(!count){modal('还没有记下第一杆','<p>先记录至少一洞成绩，再结束本轮。空白球局不会作为 0 杆成绩保存。</p>',`<div class="modal-actions">${action('close','继续记录','btn primary')}</div>`);return;}const missing=r.players.reduce((n,p)=>n+(p.withdrawn?0:r.holes.length-G.summary(r,p.id).played),0);const partial=missing>0||r.players.some(p=>p.withdrawn);confirmBox(partial?'按部分完成结束？':'结束这场好球？',partial?`还有 ${missing} 条成绩未填写${r.players.some(p=>p.withdrawn)?'，并有球友中途退出':''}。已有成绩会保留，不会把空白记成 0 杆。`:'所有参与球友均已完成记录。结束后可查看、分享，也可以更正成绩。',()=>{if(update(d=>{const x=d.rounds.find(x=>x.id===id);x.status='finished_complete';x.updatedAt=Date.now();x.completedAt=Date.now();x.revision++;})){undo=null;nav('result/'+id);toast('这一轮，已好好收下');}},partial?'保存部分成绩':'结束并查看成绩');}
function beginEdit(id,hole,pid){const r=db.rounds.find(r=>r.id===id);if(!r)return;if(!R.isFinished(r)){resume(id);return;}edit={id,original:G.clone(r),copy:G.clone(r)};edit.copy.status='active';if(hole)edit.copy.currentHole=Number(hole);if(pid)edit.copy.currentPlayer=pid;scoreHalf=null;undo=null;nav('score/'+id);}
function saveEdit(){if(!edit)return;const e=edit;if(!e.copy.players.some(p=>G.summary(e.copy,p.id).played))return toast('整场至少保留一条成绩；清空整场请使用删除');confirmBox('保存本次更正？','总杆、排名、历史和个人统计都会一起更新。已保存的分享图片需要重新生成。',()=>{const next=G.clone(e.copy);next.status='finished_complete';next.updatedAt=Date.now();next.revision=(e.original.revision||0)+1;next.corrections=[...(e.original.corrections||[]),{at:Date.now(),before:e.original.scores,after:next.scores}];if(update(d=>d.rounds[d.rounds.findIndex(r=>r.id===e.id)]=next)){edit=null;undo=null;nav('result/'+e.id);toast('成绩已更正，相关统计已更新');}},'确认更正');}
function friendForm(id){const f=db.friends.find(f=>f.id===id)||{name:'',remark:''};modal(id?'编辑球友':'添加常用球友',`<form data-form="friend" data-id="${id||''}"><div class="field"><label>昵称</label><input name="name" value="${esc(f.name)}" maxlength="20" required placeholder="输入球友昵称"></div><div class="field"><label>备注（选填）</label><input name="remark" value="${esc(f.remark||'')}" maxlength="40" placeholder="例如：周末球友"></div><p class="tiny">修改昵称不改变历史球局里的姓名记录。</p><button type="submit" class="btn primary full" style="margin-top:20px">保存球友</button></form>`);}
function profileForm(){modal('我的高尔夫档案',`<form data-form="profile"><div class="field"><label>昵称</label><input name="name" maxlength="20" required value="${esc(db.profile.name)}"></div><div class="field"><label>一句话介绍</label><input name="bio" maxlength="60" value="${esc(db.profile.bio)}"></div><div class="field"><label>自填差点（选填）</label><input type="number" step="0.1" min="-10" max="54" name="handicap" value="${db.profile.handicap??''}" placeholder="未填写"></div><p class="tiny">仅展示你的自填信息，不作为官方差点或排名依据。</p><button type="submit" class="btn primary full" style="margin-top:20px">保存资料</button></form>`);}
function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function backup(){downloadBlob(new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),`青野-${mode==='demo'?'示例':'我的'}记录-${G.date()}.json`);toast('备份文件已准备下载');}
let importPending=null,shareImage=null;
function importModal(){importPending=null;modal('恢复数据备份',`<p>导入只影响当前“${mode==='demo'?'示例体验':'我的记录'}”模式。请先导出当前数据，再选择备份文件。</p><div class="field"><label>选择 JSON 备份文件（最多 10 MB）</label><input type="file" id="backup-file" accept=".json,application/json"></div><div id="import-status" class="notice">选择文件后会先检查格式，不会立即覆盖记录。</div>${action('export','先导出当前备份','btn outline full')}`);}
async function readBackup(file){if(!file)return;if(file.size>10*1024*1024)return toast('文件超过 10 MB');try{const parsed=G.validateBackup(JSON.parse(await file.text()));importPending=parsed;$('#import-status').innerHTML=`<div><b>校验通过</b><p>包含 ${parsed.rounds.length} 场球局、${parsed.friends.length} 位球友。恢复将替换当前模式的所有记录。</p>${action('restore-backup','确认恢复这些记录','btn primary small','style="margin-top:12px"')}</div>`;}catch(e){importPending=null;$('#import-status').textContent='无法恢复：'+e.message+'。原数据没有改变。';}}
function drawRounded(ctx,x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
async function showShare(id){const r=db.rounds.find(r=>r.id===id);if(!r)return;modal('分享这一场好球','<div class="loading">正在生成你的成绩卡…</div>');const c=document.createElement('canvas');c.width=750;c.height=1050;const x=c.getContext('2d'),s=G.summary(r,'me');x.fillStyle='#f2f5ec';x.fillRect(0,0,750,1050);const photo=new Image();photo.src='assets/course.jpg';try{await photo.decode();x.save();x.beginPath();x.roundRect(42,42,666,300,24);x.clip();x.drawImage(photo,0,50,1200,650,42,42,666,300);const grad=x.createLinearGradient(0,90,0,342);grad.addColorStop(0,'#173d2900');grad.addColorStop(1,'#173d29d9');x.fillStyle=grad;x.fillRect(42,42,666,300);x.restore();}catch{drawRounded(x,42,42,666,300,24,'#236346');}
 const text=(txt,px,py,size,color='#263f2e',align='left')=>{x.fillStyle=color;x.textAlign=align;x.font=`${size}px -apple-system, "PingFang SC", sans-serif`;x.fillText(txt,px,py);};text('青 野  ·  QINGYE GOLF',72,93,19,'#fff');text('每一场好球，都值得记住。',72,283,32,'#fff');text(mode==='demo'?'示例成绩 · 演示数据':'我的高尔夫时光',375,390,18,'#859676','center');const cname=r.courseName;if(cname.length>17){text(cname.slice(0,17),375,438,29,'#294730','center');text(cname.slice(17),375,476,25,'#294730','center');}else text(cname,375,446,29,'#294730','center');text(`${r.date} · ${r.holes.length} 洞 · ${r.players.length} 位球友`,375,506,18,'#819174','center');text(s.totalText,375,651,124,'#236346','center');text(`总杆  ·  ${s.diffText}  ·  已记录 ${s.played}/${r.holes.length} 洞`,375,694,22,'#667e58','center');drawRounded(x,72,745,606,120,18,'#e7eedf');[['前九',s.frontN?s.front:'—'],['后九',s.backN?s.back:'—'],['推杆（'+s.puttN+'洞）',s.puttN?s.putts:'—']].forEach(([label,val],i)=>{text(String(val),173+i*202,800,31,'#335d3b','center');text(label,173+i*202,837,17,'#819174','center');});text(esc(db.profile.name).replaceAll('&amp;','&'),375,918,23,'#4a6c3e','center');text(s.complete?'享受挥杆，也享受沿途风景。':'部分完成 · 空白球洞未计入成绩',375,960,18,'#829174','center');text('QINGYE · 修订 '+r.revision+(r.changeLog?.some(x=>x.kind==='correction')?' · 已更正':''),375,1006,13,'#a0ae93','center');shareImage={canvas:c,url:c.toDataURL('image/png'),id};modal('分享这一场好球',`<p>只包含我的成绩。长按图片或点击保存，可由你自行分享。</p><div class="share-preview"><img src="${shareImage.url}" alt="${esc(r.courseName)}成绩卡"></div><div class="modal-actions">${action('close','关闭','btn outline')}${action('save-share',icon('download')+' 保存成绩图片','btn primary')}</div>`);}
async function handleAction(el,event){const a=el.dataset.action,id=el.dataset.id,v=el.dataset.value;
 switch(a){
 case 'go':closeModal();nav(el.dataset.path);break;
 case 'back':{const back={score:'play',create:'courses?select=1',course:'courses',manual:'courses?select=1',card:(edit?'score/':'result/')+route.id,result:'history',distance:'score/'+route.id,settings:'profile',stats:'profile',friends:'profile',history:'profile',courses:'home'};nav(back[route.name]||'home');break;}
 case 'close':closeModal();break;
 case 'backdrop':if(event.target===el)closeModal();break;
 case 'confirm':{const cb=modalCallback;closeModal();if(cb)cb();break;}
 case 'switch-mode':if(edit)return toast('请先提交或取消更正');mode=mode==='demo'?'own':'demo';try{localStorage.setItem(storagePrefix+'.mode',mode);}catch{}load();undo=null;scoreHalf=null;courseFilter='all';courseQuery='';histQuery='';histFilter='all';closeModal();nav('home');toast(mode==='demo'?'已进入示例体验':'已切换到我的独立记录');break;
 case 'reset-demo':confirmBox('恢复初始示例？','仅重置示例体验里的修改，你的个人记录不受影响。',()=>{if(persist(G.seeded())){render();toast('示例已恢复');}},'恢复示例');break;
 case 'start':start();break;
 case 'resume':resume(id);break;
 case 'favorite':if(update(d=>{if(d.favorites.includes(id))d.favorites=d.favorites.filter(x=>x!==id);else d.favorites.push(id);})){render();toast(db.favorites.includes(id)?'已收藏球场':'已取消收藏');}break;
 case 'course-filter':courseFilter=v;render();break;
 case 'show-favorites':courseFilter='favorites';nav('courses');break;
 case 'draft-holes':changeDraft(d=>{d.holes=v;d.start=v==='back'?10:1;});break;
 case 'draft-start':changeDraft(d=>d.start=Number(v));break;
 case 'add-player':addPlayerModal();break;
 case 'choose-friend':{const f=db.friends.find(f=>f.id===id);if(!f||db.draft.players.length>=4)return;closeModal();changeDraft(d=>{if(!d.players.some(p=>p.id===id))d.players.push({id:f.id,name:f.name,tee:d.players[0].tee});});break;}
 case 'remove-player':changeDraft(d=>d.players=d.players.filter(p=>p.id!==id));break;
 case 'create-round':createRound();break;
 case 'select-player':moveTo(round().currentHole,id);break;
 case 'half':scoreHalf=v;render();break;
 case 'cell':{const rid=el.dataset.rid,r=db.rounds.find(r=>r.id===rid);if(!r)return;if(R.isFinished(r)&&!edit){confirmBox('更正这洞成绩？',`${r.players.find(p=>p.id===id)?.name} · 第 ${el.dataset.hole} 洞。更正保存后会同步更新个人统计。`,()=>beginEdit(rid,el.dataset.hole,id),'进入更正');}else{const n=G.clone(round(rid));n.currentHole=Number(el.dataset.hole);n.currentPlayer=id;if(saveRound(n,round(rid))){scoreHalf=n.currentHole>9?'back':'front';nav('score/'+rid);}}break;}
 case 'score-step':{const {h,s,p}=current();if(p.withdrawn)return;const n={strokes:s?s.strokes:h.par,putts:null,penalties:null,fairway:null,gir:null,...s};n.strokes+=Number(el.dataset.delta);writeScore(n);break;}
 case 'record-par':{const {h}=current();writeScore({strokes:h.par,putts:null,penalties:null,fairway:null,gir:null});break;}
 case 'score-input':{const {h,s}=current();modal('输入本洞总杆',`<form data-form="score"><p class="muted">第 ${h.number} 洞 · Par ${h.par}，总杆已包含罚杆。</p><div class="field"><input name="strokes" type="number" inputmode="numeric" min="1" max="30" step="1" required value="${s?.strokes??h.par}" aria-label="本洞总杆"></div><button type="submit" class="btn primary full">保存总杆</button></form>`);break;}
 case 'clear-score':confirmBox('清空当前成绩？','只清空这位球友在当前洞的成绩与技术记录，之后可以撤销。',()=>writeScore(null),'清空本洞');break;
 case 'undo':{if(!undo||undo.rid!==round()?.id)return;const restored=G.setScore(round(),undo.pid,undo.hole,undo.previous);if(saveRound(restored)){undo=null;render();toast('已撤销上一次修改');}break;}
 case 'toggle-tech':technical=!technical;render();break;
 case 'tech-hit':{const {s}=current();if(!s)return;writeScore({...s,[el.dataset.key]:v==='null'?null:v==='true'});break;}
 case 'previous':{const r=round(),i=r.playOrder.indexOf(r.currentHole);if(i>0)moveTo(r.playOrder[i-1]);break;}
 case 'next':{const r=round(),i=r.playOrder.indexOf(r.currentHole);if(i===r.playOrder.length-1)return finish(r.id);const missing=r.players.filter(p=>!p.withdrawn&&!r.scores[p.id][r.currentHole]);if(missing.length)confirmBox('还有球友未记分',`${missing.map(p=>p.name).join('、')}还没有填写本洞成绩。可以先跳过，稍后回来补记。`,()=>moveTo(r.playOrder[i+1]),'跳过，稍后补记');else moveTo(r.playOrder[i+1]);break;}
 case 'pause':if(edit)return toast('更正模式请先提交或取消修改');if(update(d=>{const r=d.rounds.find(r=>r.id===route.id);r.status='paused';r.updatedAt=Date.now();})){nav('play');toast('已暂停，记录已保留');}break;
 case 'withdraw':{const {r}=current(),p=r.players.find(p=>p.id===id);confirmBox(p.withdrawn?'恢复参与？':'标记中途退出？',p.withdrawn?'已有成绩会保留，可以继续记分。':'此前成绩会保留，不计入完整比赛最终名次。',()=>{const n=G.clone(r);n.players.find(p=>p.id===id).withdrawn=!p.withdrawn;if(saveRound(n))render();},p.withdrawn?'恢复参与':'标记退出');break;}
 case 'finish':finish(id);break;
 case 'begin-edit':beginEdit(id);break;
 case 'save-edit':saveEdit();break;
 case 'cancel-edit':if(edit)confirmBox('放弃本次更正？','原来的成绩不会改变。',()=>{const id=edit.id;edit=null;undo=null;nav('result/'+id);},'放弃更正');break;
 case 'delete-round':{const r=db.rounds.find(r=>r.id===id);confirmBox('删除这场球局？',`${r.courseName} · ${r.date}。本机删除后无法撤销，请先确认已备份。`,()=>{if(update(d=>d.rounds=d.rounds.filter(r=>r.id!==id))){nav('history');toast('球局已删除');}},'删除球局');break;}
 case 'hist-filter':histFilter=v;render();break;
 case 'stats-size':statsSize=Number(v);render();break;
 case 'new-friend':friendForm();break;
 case 'edit-friend':friendForm(id);break;
 case 'remove-friend':{const f=db.friends.find(f=>f.id===id);confirmBox('移除常用球友？',`将 ${f.name} 从常用列表移除，历史球局和成绩会完整保留。`,()=>{if(update(d=>d.friends=d.friends.filter(f=>f.id!==id)))render();},'移除球友');break;}
 case 'friend-detail':{const f=db.friends.find(f=>f.id===id),rs=allSorted().filter(r=>r.players.some(p=>p.id===id));modal(f.name+'的共同球局',`<p>仅包含你记录过的共同球局。</p>${rs.map(r=>go('result/'+r.id,`<span class="grow"><b>${esc(r.courseName)}</b><small style="display:block;color:#91a085;margin-top:5px">${r.date} · ${G.summary(r,id).played}/${r.holes.length} 洞</small></span><b>${G.summary(r,id).totalText} 杆</b>`,'menu-row')).join('')}`);break;}
 case 'edit-profile':profileForm();break;
 case 'unit':if(update(d=>d.settings.unit=v))render();break;
 case 'toggle-unit':if(update(d=>d.settings.unit=d.settings.unit==='yd'?'m':'yd'))render();break;
 case 'pref-tech':if(update(d=>d.settings.technical=!d.settings.technical)){technical=db.settings.technical;render();}break;
 case 'export':backup();break;
 case 'retry-upgrade':load();render();break;
 case 'raw-export':downloadBlob(new Blob([localStorage.getItem(key())||localStorage.getItem(`${storagePrefix}.${mode}.v2`)||''],{type:'text/plain'}),'青野-原始数据.txt');break;
 case 'import':importModal();break;
 case 'restore-backup':{const data=importPending;if(!data)return;confirmBox('最后确认：替换当前记录','建议先保留导出的旧备份。恢复成功后会重新计算全部成绩和统计。',()=>{if(persist(data)){closeModal();undo=null;nav('home');toast('数据已恢复');}},'替换并恢复');break;}
 case 'cloud-info':modal('数据保存在当前浏览器','<p>当前 H5 为本地可用版，不连接云端，也不会声称已经同步。你的个人记录与示例数据分别保存。换设备时，请先导出 JSON 备份，在新设备导入。</p>');break;
 case 'about':modal('青野 · 为热爱挥杆','<p>一款专注记分的轻量高尔夫工具。沿用项目确认的清新自然风格：白色、深绿、球场实景与圆角卡片。</p><div class="notice">H5 体验版 · 本地保存<br>内置球场为演示资料；测距为球道示意。原始 8 张设计图未同步到当前项目，本版依据已确认的文字规范与项目素材实现。</div>');break;
 case 'share':await showShare(id);break;
 case 'save-share':if(shareImage)shareImage.canvas.toBlob(b=>{if(b){downloadBlob(b,`青野-成绩卡-${G.date()}.png`);toast('成绩卡已准备下载');}},'image/png');break;
 case 'demo-distance':demoDistance=demoDistance===158?143:demoDistance===143?121:158;render();toast('已移动示例位置');break;
 case 'locate':{if(!navigator.geolocation){locationMessage='当前浏览器不支持定位；记分仍可正常使用。';render();break;}locationMessage='正在请求手机位置…';$('#location-message').textContent=locationMessage;navigator.geolocation.getCurrentPosition(p=>{locationMessage=`已获取当前位置，报告精度约 ${Math.round(p.coords.accuracy)} 米。由于缺少真实果岭点位，未计算实地距离。`;if($('#location-message'))$('#location-message').textContent=locationMessage;},e=>{locationMessage=e.code===1?'定位未授权。你仍然可以正常记分。':'暂时无法定位，请检查系统定位与网络。';if($('#location-message'))$('#location-message').textContent=locationMessage;},{enableHighAccuracy:true,timeout:12000,maximumAge:0});break;}
 }
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;handleAction(el,event).catch(e=>toast('操作未完成：'+e.message));});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='course-search'){courseQuery=el.value.trim();$('#course-list').innerHTML=courseCards();}if(el.id==='history-search'){histQuery=el.value.trim();$('#history-list').innerHTML=historyList();}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='draft-date'||el.id==='draft-time')update(d=>d.draft[el.id==='draft-date'?'date':'time']=el.value);if(el.dataset.tee)update(d=>d.draft.players.find(p=>p.id===el.dataset.tee).tee=el.value);if(el.dataset.tech){const {s}=current();if(s)writeScore({...s,[el.dataset.tech]:el.value===''?null:Number(el.value)});}if(el.id==='stats-days'){statsDays=Number(el.value);render();}if(el.id==='manual-count')$('#manual-holes').innerHTML=manualHoles(Number(el.value));if(el.id==='backup-file')readBackup(el.files[0]);});
document.addEventListener('submit',event=>{const f=event.target;if(!f.dataset.form)return;event.preventDefault();const form=new FormData(f),name=String(form.get('name')||'').trim();try{
 switch(f.dataset.form){
 case 'temp-player':{if(!name||name.length>20)throw Error('请输入 1–20 个字符的昵称');const id=G.uid();if(update(d=>{if(d.draft.players.length>=4)throw Error('同组最多 4 人');d.draft.players.push({id,name,tee:d.draft.players[0].tee});if(form.has('save'))d.friends.push({id,name});})){closeModal();render();}break;}
 case 'friend':{if(!name||name.length>20)throw Error('请输入 1–20 个字符的昵称');const id=f.dataset.id,remark=String(form.get('remark')||'').trim().slice(0,40);if(update(d=>{if(id){const x=d.friends.find(x=>x.id===id);x.name=name;x.remark=remark;}else d.friends.push({id:G.uid(),name,remark});})){closeModal();render();toast('球友已保存');}break;}
 case 'profile':{if(!name||name.length>20)throw Error('请输入 1–20 个字符的昵称');const hs=String(form.get('handicap')||'').trim(),h=hs===''?null:Number(hs);if(h!==null&&(!Number.isFinite(h)||h< -10||h>54))throw Error('请输入有效的自填差点');if(update(d=>d.profile={...d.profile,name,bio:String(form.get('bio')||'').trim().slice(0,60),handicap:h})){closeModal();render();toast('个人资料已更新');}break;}
 case 'score':{const {s,h}=current(),next={strokes:Number(form.get('strokes')),putts:null,penalties:null,fairway:null,gir:null,...s};next.strokes=Number(form.get('strokes'));G.validate(next,h.par);closeModal();writeScore(next);break;}
 case 'manual':{if(!name)throw Error('请填写球场名称');const count=Number(form.get('count')),pars=Array.from({length:count},(_,i)=>Number(form.get('par-'+(i+1))));if(![9,18].includes(count)||pars.some(p=>![3,4,5].includes(p)))throw Error('标准杆配置无效');const c={id:G.uid(),name,city:String(form.get('city')||'').trim(),holes:count,pars,par:pars.reduce((a,b)=>a+b,0),tees:['未指定','白色发球台','蓝色发球台','红色发球台'],photo:0,demo:false,tag:'我的球场',subtitle:'每一场，都值得认真记录',lengths:[]};if(update(d=>d.courses.push(c)))nav('create/'+c.id);break;}
 }
 }catch(e){toast(e.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const focusable=[...$('#modal-root .modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(edit){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===key()&&!edit){load();render();toast('已载入其他标签页保存的记录');}});
